import type { EntityListResult, EntityType, Organization, ResolvePathResult } from './api/entities';

export interface PublicPageBootstrap {
  path: string;
  ownerSlug: string;
  kind: 'workspace' | 'entity' | 'entity-type';
  resolvedPath?: ResolvePathResult;
  ownerResolvedPath?: ResolvePathResult;
  entityTypeSlug?: string;
  entityType?: EntityType | null;
  entityList?: EntityListResult;
}

function normalizePath(path: string): string {
  const [pathname = ''] = path.split('?', 2);
  return `/${pathname.replace(/^\/+|\/+$/g, '')}`;
}

export function getPublicBootstrap(): PublicPageBootstrap | null {
  if (typeof window === 'undefined') return null;
  return window.__LOBU_PUBLIC_BOOTSTRAP__ ?? null;
}

export function getPublicBootstrapOrganizationFromBootstrap(
  bootstrap: PublicPageBootstrap | null | undefined
): Organization | null {
  const workspace = bootstrap?.resolvedPath?.workspace ?? bootstrap?.ownerResolvedPath?.workspace;
  if (!bootstrap || !workspace) return null;

  return {
    id: workspace.id,
    name: workspace.name || workspace.slug || bootstrap.ownerSlug,
    slug: workspace.slug || bootstrap.ownerSlug,
    logo: null,
    description: null,
    created_at: '',
    is_member: false,
    visibility: 'public',
  };
}

export function getPublicBootstrapOrganization(): Organization | null {
  return getPublicBootstrapOrganizationFromBootstrap(getPublicBootstrap());
}

export function getResolvedPathInitialData(path: string): ResolvePathResult | undefined {
  const bootstrap = getPublicBootstrap();
  if (!bootstrap) return undefined;

  const normalizedPath = normalizePath(path);
  if (bootstrap.resolvedPath && normalizePath(bootstrap.path) === normalizedPath) {
    return bootstrap.resolvedPath;
  }

  const ownerPath = `/${bootstrap.ownerSlug}`;
  if (normalizePath(ownerPath) === normalizedPath) {
    return bootstrap.ownerResolvedPath ?? bootstrap.resolvedPath;
  }

  return undefined;

