describe('getSubdomainZone', () => {
  afterEach(() => {
    __resetSubdomainCacheForTests();
  });

  // lobu#2183: a self-hoster behind a reverse proxy on service.my-domain.com
  // had the first label read as an org slug, and was redirected to
  // {org}.my-domain.com — a host their proxy did not serve. Subdomain mode is
  // opt-in now, so an unconfigured deployment stays on path-based routing.
  it('returns null when the server declared no zone', () => {
    expect(getSubdomainZone('service.my-domain.com')).toBeNull();
  });

  it('never infers a zone from hostname shape', () => {
    expect(getSubdomainZone('a.b.c.example.com')).toBeNull();
    expect(getSubdomainZone('lobu-example.com')).toBeNull();
  });

  it('uses the zone the server declared', () => {
    setRuntimeSubdomainZone('lobu.ai');
    expect(getSubdomainZone('delivery.lobu.ai')).toBe('lobu.ai');
  });

  it('normalizes a leading dot and casing from the server value', () => {
    setRuntimeSubdomainZone('.Lobu.AI');
    expect(getSubdomainZone('delivery.lobu.ai')).toBe('lobu.ai');
  });

  it('treats a blank declared zone as no zone', () => {
    setRuntimeSubdomainZone('   ');
    expect(getSubdomainZone('service.my-domain.com')).toBeNull();
  });
});

describe('buildOwnerHref', () => {
  afterEach(() => {
    __resetSubdomainCacheForTests();
  });

  // The reporter's redirect: creating an org on an unconfigured self-host must
  // stay in-app rather than jumping to a subdomain the proxy cannot serve.
  it('stays path-based on a self-host with no declared zone', () => {
    __resetSubdomainCacheForTests('service.my-domain.com');
    expect(buildOwnerHref('acme')).toEqual({ kind: 'spa', to: '/acme' });
  });

  it('still crosses hosts on a configured per-org subdomain', () => {
    __resetSubdomainCacheForTests('delivery.lobu.ai');
    setRuntimeSubdomainZone('lobu.ai');
    expect(buildOwnerHref('acme')).toEqual({
      kind: 'cross-host',
      href: 'https://acme.lobu.ai/',
    });
  });

  it('returns the stripped path when the target is the current subdomain', () => {
    __resetSubdomainCacheForTests('delivery.lobu.ai');
    setRuntimeSubdomainZone('lobu.ai');
    expect(buildOwnerHref('delivery')).toEqual({ kind: 'spa', to: '/' });
  });
});

