  if (currentSubdomain === targetSlug) {
    return { kind: 'spa', to: '/' };
  }
  const zone = getSubdomainZone();
  if (!zone) {
    return { kind: 'spa', to: `/${targetSlug}` };
  }
  return { kind: 'cross-host', href: `${window.location.protocol}//${targetSlug}.${zone}/` };
}

