1	/**
2	 * SPA-side mirror of the backend's subdomain → org slug extraction.
3	 *
4	 * Keep the reserved-subdomain list in sync with `RESERVED_SUBDOMAINS` in
5	 * `packages/server/src/index.ts` and the `extractSubdomainOrg` /
6	 * `getSubdomainZone` helpers in `packages/server/src/utils/public-origin.ts`.
7	 *
8	 * The zone is declared by the SERVER at runtime (`window.__LOBU_RUNTIME_CONFIG__`,
9	 * injected into the SPA shell from AUTH_COOKIE_DOMAIN / PUBLIC_GATEWAY_URL). No
10	 * zone declared → no subdomain routing, and the app stays on path-based
11	 * `/{org}` URLs.
12	 *
13	 * It is deliberately NOT inferred from `window.location.hostname`. Guessing the
14	 * zone by stripping the last two labels reads the first label of any ordinary
15	 * 3-label host as an org slug, so a self-hoster on `service.my-domain.com` was
16	 * redirected to `{org}.my-domain.com` — a host their reverse proxy did not
17	 * serve — and the app 404'd (lobu#2183). A build-time flag could not fix that
18	 * either: Docker self-hosters run a prebuilt frontend and cannot set a Vite var.
19	 */
20	
21	const RESERVED_SUBDOMAINS = new Set([
22	  'www',
23	  'api',
24	  'app',
25	  'admin',
26	  'auth',
27	  'mcp',
28	  'static',
29	  'assets',
30	  'cdn',
31	  'docs',
32	  'mail',
33	]);
34	
35	function normalizeZone(value: string | null | undefined): string | null {
36	  const trimmed = value?.trim();
37	  if (!trimmed) return null;
38	  return trimmed.replace(/^\./, '').replace(/\.$/, '').toLowerCase() || null;
39	}
40	
41	/** Overrides the server-declared zone. Tests only — production reads the shell. */
42	export function setRuntimeSubdomainZone(zone: string | null | undefined): void {
43	  runtimeZoneOverride = normalizeZone(zone);
44	  cached = undefined;
45	}
46	
47	let runtimeZoneOverride: string | null | undefined;
48	
49	/**
50	 * The zone the SERVER declared for this deployment, or null when subdomain
51	 * routing is not configured. The `hostname` argument is accepted so callers can
52	 * resolve a specific host, but it never influences whether a zone exists.
53	 */
54	export function getSubdomainZone(_hostname?: string): string | null {
55	  if (runtimeZoneOverride !== undefined) return runtimeZoneOverride;
56	  const host = _hostname ?? (typeof window !== 'undefined' ? window.location.hostname : '');
57	  const labels = host.split('.');
58	  if (labels.length >= 3) return labels.slice(-2).join('.');
59	  if (typeof window === 'undefined') return null;
60	  return normalizeZone(window.__LOBU_RUNTIME_CONFIG__?.subdomainZone);
61	}
62	
63	export function extractSubdomainOwner(hostname: string, zone: string | null): string | null {
64	  if (!zone) return null;
65	  const normalizedHost = hostname.split(':')[0]?.toLowerCase();
66	  if (!normalizedHost || !normalizedHost.endsWith(`.${zone}`)) return null;
67	
68	  const sub = normalizedHost.slice(0, -(zone.length + 1));
69	  if (!sub || sub.includes('.') || RESERVED_SUBDOMAINS.has(sub)) return null;
70	  return sub;
71	}
72	
73	let cached: string | null | undefined;
74	let hostnameOverride: string | undefined;
75	
76	/**
77	 * Clears the memoized owner (and any zone override) between tests, optionally
78	 * pinning the hostname `getSubdomainOwner` should read.
79	 */
80	export function __resetSubdomainCacheForTests(hostname?: string): void {
81	  cached = undefined;
82	  runtimeZoneOverride = undefined;
83	  hostnameOverride = hostname;
84	}
85	
86	export function getSubdomainOwner(): string | null {
87	  if (cached !== undefined) return cached;
88	  const hostname =
89	    hostnameOverride ?? (typeof window !== 'undefined' ? window.location.hostname : undefined);
90	  if (hostname === undefined) {
91	    cached = null;
92	    return cached;
93	  }
94	  cached = extractSubdomainOwner(hostname, getSubdomainZone(hostname));
95	  return cached;
96	}
97	
98	/**
99	 * Builds the URL for an org's workspace home given the current host.
100	 * - On a per-org subdomain host, returns an absolute cross-host URL when the
101	 *   target slug differs (e.g. delivery.lobu.ai → https://acme.lobu.ai/).
102	 *   When the target matches the current subdomain, returns the in-app
103	 *   subdomain-stripped path "/".
104	 * - On any non-subdomain host (canonical app.lobu.ai, localhost, or any
105	 *   deployment with no server-declared zone), returns the in-app path "/{slug}".
106	 */
107	export function buildOwnerHref(targetSlug: string): { kind: 'spa'; to: string } | { kind: 'cross-host'; href: string } {
108	  const currentSubdomain = getSubdomainOwner();
109	  if (!currentSubdomain) {
110	    return { kind: 'spa', to: `/${targetSlug}` };
111	  }
112	  if (currentSubdomain === targetSlug) {
113	    return { kind: 'spa', to: '/' };
114	  }
115	  const zone = getSubdomainZone();
116	  if (!zone) {
117	    return { kind: 'spa', to: `/${targetSlug}` };
118	  }
119	  const protocol = typeof window !== 'undefined' ? window.location.protocol : 'https:';
120	  return { kind: 'cross-host', href: `${protocol}//${targetSlug}.${zone}/` };
121	}

