/**
 * Injects deployment config the SPA needs before it renders, as
 * `window.__LOBU_RUNTIME_CONFIG__`.
 *
 * Separate from `__LOBU_PUBLIC_BOOTSTRAP__`, which is only emitted for SSR'd
 * public org pages: the subdomain zone has to be readable on every load
 * (sign-in included), and it cannot be a build-time Vite var because Docker
 * self-hosters run a prebuilt frontend (lobu#2183).
 *
 * Injected before any module script so the value is set before app code reads
 * it. Callers must apply this to EVERY html response that boots the SPA.
 */
export function injectRuntimeConfig(templateHtml: string): string {
  const zone = getSubdomainZone();
  const script = `<script>window.__LOBU_RUNTIME_CONFIG__=${serializeForScript({
    subdomainZone: zone,
  })};</script>`;

  // Prefer </head>; fall back to prepending so a template without one still
  // gets the value ahead of the app bundle rather than silently losing it.
  return templateHtml.includes('</head>')
    ? templateHtml.replace('</head>', `${script}\n</head>`)
    : `${script}${templateHtml}`;
}

