 * `{sub}.{canonicalHost}`.
 *
 * Never returns a loopback host or bare IP: `{org}.127.0.0.1` is not a
 * resolvable name, so declaring one as the zone would send the SPA to a host
 * that cannot exist (the local-dev shape of lobu#2183).
 */
export function getSubdomainZone(
  configuredOrigin = getConfiguredPublicOrigin(),
  cookieDomain = process.env.AUTH_COOKIE_DOMAIN
): string | null {
  const cookieZone = normalizeHost(cookieDomain);
  if (cookieZone) return isSubdomainCapableHost(cookieZone) ? cookieZone : null;

  if (!configuredOrigin) return null;
  try {
    const originZone = normalizeHost(new URL(configuredOrigin).hostname);
    return originZone && isSubdomainCapableHost(originZone) ? originZone : null;
  } catch {
    return null;
  }
}

/** False for loopback names and IP literals, which cannot carry subdomains. */
function isSubdomainCapableHost(host: string): boolean {
  if (LOCALHOST_HOSTNAMES.has(host)) return false;
  // IPv4 dotted-quad, or the bracketed/colon forms of IPv6.
  if (/^\d{1,3}(\.\d{1,3}){3}$/.test(host)) return false;
  if (host.includes(':') || host.startsWith('[')) return false;
  return true;
}

