 * Injected before any module script so the value is set before app code reads
 * it. Callers must apply this to EVERY html response that boots the SPA.
 */
export function injectRuntimeConfig(templateHtml: string): string {
  const zone = getSubdomainZone();
  const script = `<script>window.__LOBU_RUNTIME_CONFIG__=${serializeForScript({
    subdomainZone: zone,
  })};</script>`;

  // Prefer </head>; fall back to prepending so a template without one still
  // gets the value ahead of the app bundle rather than silently losing it.
  return templateHtml.includes('</head>')
    ? templateHtml.replace('</head>', `${script}\n</head>`)
    : `${script}${templateHtml}`;
}

input.new_string:
 * Injected before the FIRST script tag, not at `</head>`: Vite emits the app
 * bundle inside `<head>`, so appending at `</head>` would place this after it.
 * Module scripts are deferred today, which would paper over the ordering, but
 * a classic or inline script added later would read the value before it exists.
 *
 * Callers must apply this to EVERY html response that boots the SPA.
 */
export function injectRuntimeConfig(templateHtml: string): string {
  const zone = getSubdomainZone();
  const script = `<script>window.__LOBU_RUNTIME_CONFIG__=${serializeForScript({
    subdomainZone: zone,
  })};</script>`;

  const firstScript = templateHtml.search(/<script\b/i);
  if (firstScript !== -1) {
    return `${templateHtml.slice(0, firstScript)}${script}\n${templateHtml.slice(firstScript)}`;
  }
  // No scripts at all: fall back to </head>, then to prepending, so the value
  // is never silently dropped.
  return templateHtml.includes('</head>')
    ? templateHtml.replace('</head>', `${script}\n</head>`)
    : `${script}${templateHtml}`;
}

