func main(){
  // EXACT pattern + extract from image-policies.yaml
  re := regexp.MustCompile(`^(?P<date>\d{8})-(?P<time>\d{6})(?:-(?P<run>\d{2}))?$`)
  ex := func(t string) (float64, bool) {
    m := re.FindStringSubmatchIndex(t); if m==nil { return 0,false }
    b := re.ExpandString(nil, "${date}${time}${run}", t, m)
    f,err := strconv.ParseFloat(string(b),64); return f, err==nil
  }
  type C struct{ name, a, b string; want string }
