package main
import ("fmt";"regexp";"sort")
func main(){
  // Full 6-digit run number now affordable under alphabetical ordering.
  re := regexp.MustCompile(`^(?P<date>\d{8})-(?P<time>\d{6})(?:-(?P<run>\d{6}))?$`)
