  old, new_ := ex("20260728-071749"), ex("20260728-140000-001662")
  fmt.Printf("  old=%s (%d chars)\n  new=%s (%d chars)\n", old, len(old), new_, len(new_))
  fmt.Printf("  new > old lexicographically = %v\n", new_ > old)

