  tags := []string{"20260728-071749","20260728-135124","20260728-135124-001562","20260728-135124-001662","20260728-140000-001662"}
  ks := make([]string,0); for _,t := range tags { ks = append(ks, ex(t)) }
  sort.Strings(ks)
  for _,k := range ks { fmt.Println("  ", k) }
  fmt.Println("  selected ->", ks[len(ks)-1])
}
EOF
