/** release-please publishes lobu-vX.Y.Z; other repos' releases share this feed. */
const LOBU_TAG_PREFIX = "lobu-v";

/** Run numbers wider than the tag format's fixed 6-digit suffix must fail loudly. */
export const MAX_RUN_NUMBER = 999999;

/**
 * Build the shared timestamp tag: `<date>-<time>-<run_number>`. Both halves
 * are load-bearing, and each replaces something that failed:
 *
 * The timestamp ORDERS. Flux picks the lexicographically highest extracted
 * value, so the key has to track when a build actually ran. Ordering by
 * run_number alone breaks recovery: re-running an earlier failed release
 * after a later push republishes a LOWER number, and the recovered release
 * never deploys — exactly the rerun that unstuck `lobu-v14.4.0`.
 *
 * run_number BREAKS TIES. A release can run beside a push (they are separate
 * concurrency groups), so two builds can stamp the same second. Probing the
 * registry first does not help — that is check-then-act, and concurrent runs
 * both see the tag free before either has pushed. run_number is unique per
 * workflow, so equal tags are impossible by construction. It is the WHOLE
 * number, never truncated: taking it modulo anything reintroduces collisions,
 * because a rerun reuses an OLD run_number (re-running 1562 beside a fresh
 * 1662 yields the same suffix in the same second).
 *
 * Every component is fixed-width and zero-padded: Flux's extract concatenates
 * the groups for lexicographic comparison, so a variable-width component
 * would misorder. The matching pattern lives in the owletto submodule
 * (deploy/k8s/infrastructure/image-automation/image-policies.yaml) and also
 * accepts the older two-segment tags, which sort below a same-second
 * three-segment tag — correct, they are older.
 *
 * @param {{now: Date, runNumber: number|string}} input
 * @returns {string}
 * @throws when runNumber is not a positive integer or exceeds six digits.
 */
export function buildImageTag({ now, runNumber }) {
  const n = Number(runNumber);
  if (!Number.isInteger(n) || n < 1) {
    throw new Error(`run number '${runNumber}' is not a positive integer.`);
  }
  if (n > MAX_RUN_NUMBER) {
    throw new Error(
      `run number ${n} exceeds the 6 digits the tag format allows.`
    );
  }
  const pad = (value, width) => String(value).padStart(width, "0");
  const date = `${now.getUTCFullYear()}${pad(now.getUTCMonth() + 1, 2)}${pad(now.getUTCDate(), 2)}`;
  const time = `${pad(now.getUTCHours(), 2)}${pad(now.getUTCMinutes(), 2)}${pad(now.getUTCSeconds(), 2)}`;
  return `${date}-${time}-${pad(n, 6)}`;
}

